// Closes a checklist that no longer applies (e.g. onboarding of someone who left,
// offboarding of a cancelled separation).
func (q *Queries) SkipOpenChecklistTasks(ctx context.Context, arg SkipOpenChecklistTasksParams) (int64, error) {
	result, err := q.db.Exec(ctx, skipOpenChecklistTasks,
		arg.EmployeeID,
		arg.CompanyID,
		arg.WorkflowType,
		arg.Note,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateCustomField = `-- name: UpdateCustomField :one
UPDATE employee_custom_fields SET
    label = $3,
    options = $4,
    is_required = $5,
    is_sensitive = $6,
    sort_order = $7,
    is_active = $8,
    updated_at = NOW()
WHERE id = $1 AND company_id = $2
RETURNING id, company_id, field_key, label, field_type, options, is_required, is_sensitive, sort_order, is_active, created_at, updated_at
`

type UpdateCustomFieldParams struct {
	ID          int64    `json:"id"`
	CompanyID   int64    `json:"company_id"`
	Label       string   `json:"label"`
	Options     []string `json:"options"`
	IsRequired  bool     `json:"is_required"`
	IsSensitive bool     `json:"is_sensitive"`
	SortOrder   int32    `json:"sort_order"`
	IsActive    bool     `json:"is_active"`
}

func (q *Queries) UpdateCustomField(ctx context.Context, arg UpdateCustomFieldParams) (EmployeeCustomField, error) {
	row := q.db.QueryRow(ctx, updateCustomField,
		arg.ID,
		arg.CompanyID,
		arg.Label,
		arg.Options,
		arg.IsRequired,
		arg.IsSensitive,
		arg.SortOrder,
		arg.IsActive,
	)
	var i EmployeeCustomField
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.FieldKey,
		&i.Label,
		&i.FieldType,
		&i.Options,
		&i.IsRequired,
		&i.IsSensitive,
		&i.SortOrder,
		&i.IsActive,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertCustomFieldValue = `-- name: UpsertCustomFieldValue :exec
INSERT INTO employee_custom_field_values (company_id, employee_id, field_id, value, updated_by)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (employee_id, field_id) DO UPDATE SET
    value = EXCLUDED.value,
    updated_by = EXCLUDED.updated_by,
    updated_at = NOW()
`

type UpsertCustomFieldValueParams struct {
	CompanyID  int64  `json:"company_id"`
	EmployeeID int64  `json:"employee_id"`
	FieldID    int64  `json:"field_id"`
	Value      string `json:"value"`
	UpdatedBy  *int64 `json:"updated_by"`
}

func (q *Queries) UpsertCustomFieldValue(ctx context.Context, arg UpsertCustomFieldValueParams) error {
	_, err := q.db.Exec(ctx, upsertCustomFieldValue,
		arg.CompanyID,
		arg.EmployeeID,
		arg.FieldID,
		arg.Value,
		arg.UpdatedBy,
	)
	return err
}
